D = {
"ripwire-before-you-build": "Starting a FEATURE (multi-symbol work): get the plan, interface or size estimate from the codebase's real structure first — spike viability, ordered plan, API boundary, effort. `--lego=Iface` shows an interface's contract plus every implementor to copy. ONE symbol → ripwire-reuse-first. A small feature with an obvious home needs none of this.",
"ripwire-change-check": "Merge-SAFETY of a diff that already exists — your changes before you push, or a PR you review: blast radius, tests to run (--affected/--situ), a broken contract (--edit-check=SYM), branch conflicts and landing order (--merge-scout), work stranded on old refs (--stray-content). Code QUALITY → ripwire-quality-bar. Even a one-line leaf fix runs --edit-check first.",
"ripwire-efficient": "About to open more than ~2 files, or paste whole files, to answer one question — map first, then read only the 2-3 files the map ranks highest. The token-and-accuracy discipline for ANY read (less context is measurably MORE accurate); it fires alongside the moment skills, never instead of them. A bleeding context budget → the compress ladder inside.",
"ripwire-find-bug": "You have a SYMPTOM — crash, exception, wrong output, failing test, error string, stack trace — and don't yet know which code is responsible. Ranks candidate symbols; a trace maps onto indexed frames innermost-first; 'I changed X and it broke' → the --situ regression trace. One clear hit plus one focused read that explains the symptom is enough — fix it, don't chain more verbs.",
"ripwire-fresh-eyes": "Maintenance risk in code you did NOT write, in a subsystem already identified — 'what's gnarly / where's the rot / safe to touch?', before a refactor or on a suspected god object. Hotspots, dead code, clones, nesting profile, bus factor, co-change coupling; scope it with a DIR. Diagnoses the shape; naming the fix, or judging YOUR new code → ripwire-quality-bar. A single-lens question is a single call.",
"ripwire-graph-query": "A call-graph question the fixed verbs can't phrase — 'which high-complexity functions can reach X?', 'what in src/ has 10+ callers?'. --graph-query is a small closed expression language over the symbol graph: filter by kind, complexity or fan-in, narrow to a file or cluster, bounded callers/callees closure, and/or/not. Use when --callers/--callees/--impact alone can't ask it.",
"ripwire-handoff": "Brief someone ELSE on a subsystem — 'hand this area off': a summary for the next agent or teammate with its purpose, the 2-3 entry points (signatures + bodies), the design docs that say WHY, and hotspot/bus-factor risk scoped to that area — a compact pasteable brief, not a wall of source. Understanding it yourself → ripwire-orient.",
"ripwire-layers": "Architecture HEALTH and ENFORCEMENT — 'is this a dependency mess / any layering violations / how do I enforce module boundaries in CI?': cycles, godfiles, propagation cost, and --arch layering rules with a baseline gate, each with what to DO about a bad number. A structure overview without gating → ripwire-orient. One pass answers it; re-run only after the rules or the code change.",
"ripwire-mcp": "Wire ripwire into an agent as an MCP server — `ripwire wrap AGENT` for Claude Code, Cursor, Codex, Windsurf, Gemini, opencode, aider — and pick the right MCP verb mid-task. Also the tool-HEALTH moment: a symbol you expected is missing from the ranked output, results look stale after a rebase, 'is my ripwire setup broken?' — the index-staleness/rebuild surface says whether the answer is trustworthy.",
"ripwire-navigate": "You can NAME the symbol: who calls it, what it calls, the path from A to B, a bounded neighborhood, its full body with callers/callees, or an exact literal/regex/AST-shape match with its enclosing symbol. 'Is it safe to change X?' = the transitive blast radius, not 1-hop callers. Three or more symbols that must meet → --connect=A,B,C. Run the one verb that fits; when its answer is clear, stop.",
"ripwire-opt-remarks": "Triage clang optimization remarks (-Rpass, -Rpass-missed, -fsave-optimization-record) while editing ripwire's OWN C++: 'loop not vectorized', 'will not be inlined', 'load clobbered', LICM failed to hoist — is this remark worth a diff, or is a build flag (LTO/PGO) the real fix? Contributor-only: about compiling this tool, never about running its verbs.",
"ripwire-orient": "Landing COLD in an unfamiliar repo or subsystem, before editing: the lay of the land, main subsystems and entry points, 'how does X work / where is Y', an architecture overview or module map, or rebuilding context after a compaction. A ladder from a one-screen map up to communities and diagrams instead of blind grep; --doctor/--skipped when the map looks short. A NAMED symbol → ripwire-navigate. Stop at the first rung that answers.",
"ripwire-perf-target": "A MEASURED performance problem: start from a benchmark, flame graph or profiler sample, pin the workload, then locate the hot symbol the profile names, map its callers/callees and test structural hypotheses (complexity, churn, coupling, nesting; memory-bound → --field-affinity cache-line layout). Static metrics are change-risk signals, not runtime heat. Inspect only the symbols the profile names.",
"ripwire-quality-bar": "Code QUALITY of what YOU just wrote, right before commit / PR / 'it's done': --quality-delta reports only what got WORSE across 10 kinds (complexity, nesting, params, duplication, dead code, API surface, error masking, clones…), exits non-zero on new debt, then names the refactor a measured shape calls for and proves the fix landed. Merge safety → ripwire-change-check. Even a single-line leaf fix runs the one-shot delta.",
"ripwire-reuse-first": "About to write ONE symbol — a function, class, helper, even a 'quick' one-liner — or add a dependency: reuse before you reinvent. Finds the existing building block, the repo's best exemplar to imitate (by ROLE, not text similarity), the duplicate you'd recreate, and whether the dependency is already vendored. A whole feature → ripwire-before-you-build. One --exemplar or --grep call at most.",
"ripwire-router": "Start HERE when unsure which ripwire skill fits, or asked 'which ripwire skill / how do I use ripwire / where do I start'. A moment→skill map — cold start, understand X, plan a feature, write a symbol, review my diff, debug, refactor, perf, security, handoff — plus the two reflexes that leak most: --exemplar before you write, --quality-delta before you call it done. One hop to the right skill.",
"ripwire-security-scan": "Security review: (1) vet an untrusted SKILL.md, skills/ dir or .mcp.json BEFORE installing it — the built-in injection/exfiltration/path-traversal scanner (a CRITICAL verdict blocks the install) plus a manual checklist of its shell stanzas; (2) review code on an untrusted-input path (parsing, deserialization, auth, exec/eval, network handlers): unsafe-fn lint hits, taint reach, untested seams. One scan pass is the verdict.",
"ripwire-write-tests": "Write tests for EXISTING code that has none — 'this is untested, add coverage', 'what's missing a test here?'. Finds what no test reaches: --seams ranks untested cross-module call edges, the tested=1 lens shows coverage, --callers gives the symbol's outside contract, --affected proves the new test registers. Judging your own diff → ripwire-change-check. For one target one --seams or --callers pass suffices.",
}
import pathlib, re, sys, textwrap
root = pathlib.Path(sys.argv[1]) if len(sys.argv) > 1 else pathlib.Path("skills")
for name, desc in D.items():
    f = root / name / "SKILL.md"
    t = f.read_text(); parts = t.split("---", 2); fm = parts[1]
    m = re.search(r'^description:[ \t]*(.*?)(?=\n[A-Za-z_-]+:|\Z)', fm, re.S | re.M)
    wrapped = "\n".join("  " + l for l in textwrap.wrap(desc, 100))
    fm2 = fm[:m.start()] + "description: >\n" + wrapped + "\n" + fm[m.end():].lstrip("\n")
    f.write_text("---" + fm2 + "---" + parts[2])
for name, desc in sorted(D.items(), key=lambda kv: -len(kv[1])):
    print(f"{len(desc):>4} {name}")
print("total", sum(len(v) for v in D.values()))
